import {modules,entityTypes,moduleCoverage,contextReadiness} from './modules.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pill=t=>`<span class="tag">${esc(t)}</span>`;
const link=(page,label)=>`<button class="btn" data-page="${page}">${esc(label)} →</button>`;
const head=(title,text)=>`<div class="heading"><div><div class="eyebrow">Enterprise context foundation</div><h1>${esc(title)}</h1><p class="subtitle">${esc(text)}</p></div></div>`;
const options=(values,value)=>values.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('');
function recordsTable(nodes){return `<div class="table-wrap"><table class="table"><thead><tr><th>Entity</th><th>Type</th><th>Owner</th><th>Evidence</th></tr></thead><tbody>${nodes.map(n=>`<tr><td><button class="view-link" data-node="${esc(n.id)}">${esc(n.name)}</button></td><td>${esc(n.type)}</td><td>${esc(n.owner||'Unassigned')}</td><td>${pill(n.validated?'Marked validated':'Needs validation')}</td></tr>`).join('')||'<tr><td colspan="4">No matching context loaded. Add records in the Context Builder.</td></tr>'}</tbody></table></div>`;}
export function modulesView(graph){return head('Twelve modules. One enterprise context.','Explore each decision capability, the evidence it needs and its current implementation status.')+`<div class="data-health">The public prototype uses synthetic data and browser-local edits. Context workspaces are functional evidence views; their planned analytical engines are not connected.</div><div class="module-grid">${modules.map((m,i)=>{const c=moduleCoverage(graph,m);return `<section class="panel module-card"><div class="module-number">${String(i+1).padStart(2,'0')} ${pill(m.status)}</div><h2>${esc(m.name)}</h2><p>${esc(m.question)}</p><div class="module-coverage"><b>${c.present.length}/${m.types.length}</b> required entity types represented · ${c.nodes.length} records</div><div class="bar-track"><i style="width:${c.percent}%"></i></div><p class="section-caption">${c.missing.length?'Missing: '+esc(c.missing.join(', ')):'All required types have at least one record; quality still needs review.'}</p>${link('module-'+m.id,'Open module')}</section>`;}).join('')}</div>`;}
export function moduleView(graph,id){const m=modules.find(x=>x.id===id);const c=moduleCoverage(graph,m);return head(m.name,m.question)+`<div class="buttons">${pill(m.status)}${link('modules','All 12 modules')}${link('builder','Build enterprise context')}${m.route?link(m.route,'Open demo analysis'):''}</div><div class="grid-two section-gap"><section class="panel module-card"><h2>Decision evidence requirements</h2><p>${esc(m.needs)}</p><div class="tag-row">${m.types.map(pill).join('')}</div><p>Relevant entities: <b>${c.nodes.length}</b> · relationships within this module: <b>${c.links.length}</b></p><p>Evidence is shared across modules. Adding a record here through the Context Builder also makes it available to the enterprise graph.</p></section><section class="panel module-card"><h2>Context gaps</h2><p>${c.missing.length?'Add missing entity types: '+esc(c.missing.join(', '))+'.':'All required entity types are represented.'}</p><p>${c.nodes.filter(n=>!n.validated).length} relevant entities are awaiting owner validation. Representation does not establish completeness, usable metrics, or analytical readiness.</p>${link('readiness','Review context readiness')}</section></div><section class="panel section-gap"><div class="panel-head"><h2>Shared evidence records</h2></div>${recordsTable(c.nodes)}</section>`;}
export function readinessView(graph){const r=contextReadiness(graph);return head('Context readiness','Review coverage and evidence gaps before relying on transformation recommendations.')+`<div class="metric-grid">${[['Evidence metadata',r.complete+'/'+r.total,'Owner, source, date, classification, state, confidence and validation flag'],['Needs validation',r.unvalidated,'Entity and relationship records not marked validated'],['Stale or undated',r.stale,'Evidence older than 90 days, missing or invalid dates'],['Isolated entities',r.isolated.length,'Entities without any recorded relationship']].map(([label,value,note])=>`<div class="metric"><div class="metric-top">${label}</div><div class="metric-value">${value}</div><p>${note}</p></div>`).join('')}</div><div class="data-health">Coverage measures presence of required entity types, not enterprise inventory completeness. Metadata checks do not certify the truth of a record. Classification labels are metadata only; browser storage does not enforce access control.</div><section class="panel section-gap"><div class="table-wrap"><table class="table"><thead><tr><th>Module</th><th>Type coverage</th><th>Missing context</th><th></th></tr></thead><tbody>${modules.map(m=>{const c=moduleCoverage(graph,m);return `<tr><td>${esc(m.name)}</td><td>${c.present.length}/${m.types.length}</td><td>${esc(c.missing.join(', ')||'No type gaps')}</td><td>${link('module-'+m.id,'Review')}</td></tr>`;}).join('')}</tbody></table></div></section>${r.isolated.length?`<section class="panel section-gap"><div class="panel-head"><h2>Entities to connect</h2></div>${recordsTable(r.isolated)}</section>`:''}`;}
let editorKind='node',editorId='';
export function setEditor(kind,id=''){editorKind=kind;editorId=id;}
export function getEditor(){return {kind:editorKind,id:editorId};}
export function builderView(graph){
 const kind=editorKind,key=kind==='node'?'nodes':'edges',r=graph[key].find(x=>x.id===editorId)||{},editing=Boolean(r.id);
 const input=(name,label,value='',type='text',required=true)=>`<label>${label}<input class="input" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${name==='id'&&editing?'readonly':''} ${type==='number'?'min="0" step="any"':''} maxlength="500"></label>`;
 const select=(name,label,values,value)=>`<label>${label}<select class="select" name="${name}">${options(values,value)}</select></label>`;
 return head('Enterprise Context Builder','Create and maintain shared entities and relationships. Changes stay in this browser; export JSON for a reviewed handoff.')+`<div class="buttons"><button class="btn ${kind==='node'?'primary':''}" data-editor-kind="node">Entities</button><button class="btn ${kind==='edge'?'primary':''}" data-editor-kind="edge">Relationships</button>${link('data','Import / export & backend')}${link('readiness','Context readiness')}</div><div class="data-health section-gap">Use synthetic or non-sensitive records in this public demo. No shared database write or access enforcement is active. Export your changes before clearing browser storage.</div><div class="builder-layout section-gap"><section class="panel module-card"><h2>${editing?'Edit':'Add'} ${kind==='node'?'entity':'relationship'}</h2><label class="editor-picker">Choose an existing record<select class="select" id="editor-record"><option value="">Create new record</option>${graph[key].map(x=>`<option value="${esc(x.id)}" ${x.id===editorId?'selected':''}>${esc(kind==='node'?x.name:x.type+' · '+x.source+' → '+x.target)}</option>`).join('')}</select></label><form id="context-editor" class="context-form">
 ${input('id','Unique record ID',r.id||'')}
 ${kind==='node'?input('name','Entity name',r.name||'')+select('type','Entity type',[...new Set([...entityTypes,...graph.nodes.map(n=>n.type)])].sort(),r.type||'Application'):`<label>Source entity<select class="select" name="source" required>${graph.nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===r.source?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label><label>Target entity<select class="select" name="target" required>${graph.nodes.map(n=>`<option value="${esc(n.id)}" ${n.id===r.target?'selected':''}>${esc(n.name)}</option>`).join('')}</select></label>${input('type','Relationship type (for example DEPENDS_ON)',r.type||'DEPENDS_ON')}`}
 ${input('owner','Accountable owner',r.owner||'')}${input(kind==='node'?'source':'sourceRef','Evidence source / reference',kind==='node'?r.source||'':r.sourceRef||'')}
 ${input('observedAt','Evidence date',r.observedAt||new Date().toISOString().slice(0,10),'date')}${input('validUntil','Validity end (optional)',r.validUntil||'','date',false)}
 ${select('state','Fact state',['observed','approved-plan','hypothesis'],r.state||'observed')}${select('classification','Access classification',['Public','Internal','Confidential','Restricted'],r.classification||'Internal')}${select('confidence','Confidence',['Low','Medium','High'],r.confidence||'Low')}
 <label class="wide">Description<textarea class="textarea" name="description" maxlength="3000">${esc(r.description||'')}</textarea></label>
 ${kind==='node'?`<details class="wide" ${r.type==='Initiative'?'open':''}><summary>Financial and assessment fields (required for initiatives)</summary><div class="context-form">${[['investment','Investment GBP'],['annualSaving','Annual saving hypothesis GBP'],['durationMonths','Duration months'],['annualCost','Annual run cost GBP'],['businessValue','Business value (0–100)'],['health','Technical health (0–100)'],['risk','Risk (0–100)']].map(([key,label])=>input(key,label,r[key]??'','number',false)).join('')}</div><p>Initiatives require investment, annual savings and duration. Other fields are optional; missing scores prevent portfolio assessment.</p></details>`:''}
 <label class="wide check-label"><input type="checkbox" name="validated" ${r.validated?'checked':''}> Owner has validated this record (manual assertion)</label><p id="editor-error" class="wide" role="alert"></p><button class="btn primary" type="submit">${editing?'Save record':'Add record'}</button></form></section><section class="panel module-card"><h2>One connected enterprise</h2><p>Use stable IDs to avoid duplicate entities. Existing records can be edited without losing their additional imported attributes.</p><ol><li>Add entities with their source and accountable owner.</li><li>Connect entities with directed relationships.</li><li>Keep observed facts separate from plans and hypotheses.</li><li>Review evidence gaps and export the graph.</li></ol><p>The full graph supports ${entityTypes.length} suggested entity types across all twelve modules. Custom imported types remain available.</p>${link('graph','Explore graph')}<hr><h3>Persistence & governance</h3><p>Browser-local persistence is active. Neo4j reading and seeding are available through the optional local backend. Authenticated write APIs, multi-user approvals, audit history and source connectors require backend implementation.</p><p>JSON imports are validated for duplicate IDs and dangling links. Automatic entity matching is not implemented.</p></section></div>`;
}
